{
  "type": "record",
  "name": "VesselOutlier",
  "namespace": "com.example.vessels",
  "fields": [
    {
      "name": "MMSI",
      "type": "long",
      "doc": "Maritime Mobile Service Identity number."
    },
    {
      "name": "Event_Timestamp",
      "type": {
        "type": "string",
        "logicalType": "timestamp-millis"
      },
      "doc": "Timestamp of the event."
    },
    {
      "name": "Latitude",
      "type": "double",
      "doc": "Vessel's latitude."
    },
    {
      "name": "Longitude",
      "type": "double",
      "doc": "Vessel's longitude."
    },
    {
      "name": "Speed",
      "type": "double",
      "doc": "Vessel's speed."
    },
    {
      "name": "Course",
      "type": "double",
      "doc": "Vessel's course over ground."
    },
    {
      "name": "Status",
      "type": "string",
      "doc": "Vessel's navigational status (e.g., Moored)."
    },
    {
      "name": "Destination",
      "type": "string",
      "doc": "Vessel's declared destination."
    },
    {
      "name": "Outlier_Type",
      "type": "string",
      "doc": "Category of the detected outlier."
    },
    {
      "name": "Reason",
      "type": "string",
      "doc": "Detailed reason for the outlier detection."
    },
    {
      "name": "Recommendation",
      "type": "string",
      "doc": "Suggested action based on the outlier."
    },
    {
      "name": "Severity_Level",
      "type": "int",
      "doc": "Numeric rating of the severity."
    }
  ]
}

{
  "type": "record",
  "name": "GPSJammerEvent",
  "namespace": "defense.monitoring",
  "doc": "Schema für simulierte GPS-Jamming-Events basierend auf ADS-B NIC Metriken im Ostseeraum.",
  "fields": [
    {
      "name": "geohash",
      "type": "string",
      "doc": "6- oder 7-stelliger Geohash zur geografischen Identifizierung der Kachel."
    },
    {
      "name": "ts",
      "type": "string",
      "doc": "ISO 8601 Zeitstempel der Beobachtung (z.B. 2026-01-16T09:27:44)."
    },
    {
      "name": "latitude",
      "type": "double",
      "doc": "Geografische Breite des Kachel-Zentrums."
    },
    {
      "name": "longitude",
      "type": "double",
      "doc": "Geografische Länge des Kachel-Zentrums."
    },
    {
      "name": "adsb_nic",
      "type": "int",
      "doc": "Navigation Integrity Category (Wert von 0 bis 8)."
    },
    {
      "name": "signal_integrity",
      "type": "double",
      "doc": "Berechnete Signalqualität (0.05 bis 0.90)."
    },
    {
      "name": "jamming_indicator",
      "type": "boolean",
      "doc": "Indikator für aktives Jamming (True wenn NIC < 5)."
    },
    {
      "name": "event_type",
      "type": "string",
      "doc": "Typ des Ereignisses, festgesetzt auf gps_jammer_event."
    }
  ]
}

